package org.example.skillsprint.controller;

import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import jakarta.servlet.http.HttpSession;
import org.example.skillsprint.dao.UserDAO;import org.example.skillsprint.model.User;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
import java.io.IOException;import java.net.URI;import java.sql.SQLException;import java.util.Locale;import java.util.regex.Pattern;

@Controller
public class ProfileController {
    private static final Pattern EMAIL=Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");private final UserDAO dao;
    public ProfileController(UserDAO dao){this.dao=dao;}
    @GetMapping("/profile") public String view(HttpServletRequest req,Model m,HttpServletResponse res) throws IOException {HttpSession s=req.getSession(false);int id=uid(s);if(id<=0)return "redirect:/login";Object success=s.getAttribute("profileSuccess");if(success!=null){m.addAttribute("success",success);s.removeAttribute("profileSuccess");}try{User u=dao.findProfileById(id);if(u==null){res.sendError(404,"Profile not found.");return null;}m.addAttribute("profile",u);return "profile";}catch(SQLException e){req.getServletContext().log("Profile could not be loaded.",e);m.addAttribute("error","Your profile could not be loaded right now. Please try again.");return "profile";}}
    @PostMapping("/profile") public String update(@RequestParam(name="fullName",defaultValue="") String fullName,@RequestParam(name="email",defaultValue="") String email,@RequestParam(name="college",defaultValue="") String college,@RequestParam(name="branch",defaultValue="") String branch,@RequestParam(name="githubUrl",defaultValue="") String githubUrl,@RequestParam(name="linkedinUrl",defaultValue="") String linkedinUrl,HttpServletRequest req,HttpServletResponse res,Model m) throws IOException {HttpSession s=req.getSession(false);int id=uid(s);if(id<=0)return "redirect:/login";User u=new User(id,fullName.trim(),email.trim().toLowerCase(Locale.ROOT),null,empty(college.trim()),empty(branch.trim()),empty(githubUrl.trim()),empty(linkedinUrl.trim()));String e=validate(u);if(e!=null)return showError(m,u,e);try{if(dao.emailExistsForAnotherUser(u.getEmail(),id))return showError(m,u,"That email address is already used by another account.");if(!dao.updateProfile(u)){if(dao.emailExistsForAnotherUser(u.getEmail(),id))return showError(m,u,"That email address is already used by another account.");return showError(m,u,"Your profile could not be updated. Please try again.");}s.setAttribute("userName",u.getFullName());s.setAttribute("profileSuccess","Your profile was saved successfully.");return "redirect:/profile";}catch(SQLException ex){req.getServletContext().log("Profile could not be saved.",ex);return showError(m,u,"Your profile could not be saved right now. Please try again.");}}
    private String validate(User u){if(u.getFullName().trim().isEmpty())return "Full name is required.";if(u.getFullName().length()>100)return "Full name must be 100 characters or fewer.";if(u.getEmail().isEmpty())return "Email is required.";if(u.getEmail().length()>100||!EMAIL.matcher(u.getEmail()).matches())return "Enter a valid email address (100 characters or fewer).";if(len(u.getCollege())>150)return "College must be 150 characters or fewer.";if(len(u.getBranch())>100)return "Branch must be 100 characters or fewer.";if(len(u.getGithubUrl())>255)return "GitHub URL must be 255 characters or fewer.";if(len(u.getLinkedinUrl())>255)return "LinkedIn URL must be 255 characters or fewer.";if(u.getGithubUrl()!=null&&!url(u.getGithubUrl()))return "Enter a valid HTTP or HTTPS GitHub URL.";if(u.getLinkedinUrl()!=null&&!url(u.getLinkedinUrl()))return "Enter a valid HTTP or HTTPS LinkedIn URL.";return null;}
    private boolean url(String s){try{URI u=new URI(s);String scheme=u.getScheme();return u.isAbsolute()&&u.getHost()!=null&&!u.getHost().isEmpty()&&("http".equalsIgnoreCase(scheme)||"https".equalsIgnoreCase(scheme));}catch(Exception e){return false;}}
    private String showError(Model m,User u,String e){m.addAttribute("error",e);m.addAttribute("profile",u);return "profile";}
    private int uid(HttpSession s){Object v=s==null?null:s.getAttribute("userId");return v instanceof Number?((Number)v).intValue():0;}private String empty(String s){return s.isEmpty()?null:s;}private int len(String s){return s==null?0:s.length();}
}
